quests[28681] = { id = 28681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shark Tank", description = "I hate sharks.  All of my troops hate sharks too.  This is where you come in, {name}.\n\nI need you to head up to the Cape of Lost Hope and take out a huge shark named Tank.  Tank is not to be trifled with so I would bring a few friends if I were you.", sourceObjective = "You have been tasked to kill Tank, a large shark cruising the waters of the Cape of Lost Hope. The cape can be found north of here, along the northern coastline.", progress = "I don't think you guys have a chance against that shark.", completion = "No way, you actually killed him?  We are having shark tacos tonight for sure!", sourceObjectiveStatus = "unverified-source-field" }
quests[28682] = { id = 28682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claiming The Keep", description = "Have you seen the keep on the north side of the island, {name}?  That is where Keep Lord Farson runs his operation from.\n\nFarson has a small group of dedicated followers and they have been giving us trouble since we got here.  We sent a small group to investigate and they reported back on his exact position within the keep.\n\nCan you finish him off for us?", sourceObjective = "You have been asked to kill Keep Lord Farson at the Farson Hold. Farson Hold can be found on the north side of the island.", progress = "Is keep lord farson dead?", completion = "You killed him?  We have been trying to take that guy out for weeks!  We thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28683] = { id = 28683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thinning the Brood", description = "We have been trying to get a foothold in The Darkwood for weeks now but that forest is infested with spiders.  Do me a favor and see if you can thin them out enough for us to set up an attack.\n\nCareful out there, I have heard reports of Alliance troops nearby earlier in the week.", sourceObjective = "Kill 12 Darkwood Lurkers in The Darkwood. The Darkwood forest is just north of here, across the bridge on the central island.", completion = "Nice work on those spiders, {name}.  At this rate, we will be taking that forest in no time.", sourceObjectiveStatus = "unverified-source-field" }
quests[28684] = { id = 28684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sticky Task", description = "Finding supplies on the island has been difficult, to say the least.\n\nFortunately, we have found a good supply of silk in The Darkwood, just north of here.  The bad part of this story is that the silk comes from the glands on Broodmother spiders.  I need you to gather 4 of these for me.\n\nThat should be just enough to finish up this last set of shirts.", sourceObjective = "Collect 4 Sticky Silk Glands from Darkwood Broodmother spiders in The Darkwood. The Darkwood forest is just west of here, across the bridge on the central island.", progress = "Were you able to gather the sticky silk glands?", completion = "These glands will do nicely.  We are grateful for your help, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28685] = { id = 28685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave No Weapon Behind", description = "Battle supplies are hard to come by on this rock.  Every time we hold off another Alliance attack, it feels like we are fighting with sticks and stones.\n\nReports have come in that Keep Lord Farson on the north side of the island has a large stockpile of rifles that we could use.  Can you head down there and check it out?\n\nBe careful {name}, Farson's followers will do anything to protect him.", sourceObjective = "Retrieve 12 Rusty Rifles from Farson Hold on the north side of Tol Barad Peninsula.", progress = "Any luck with those rifles?", completion = "Thanks for rounding these up for us, {name}.  Kind of hard to fight a battle without any guns.", sourceObjectiveStatus = "unverified-source-field" }
quests[28686] = { id = 28686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not The Friendliest Town", description = "Have you been up to Rustberg Village yet {name}?  I would suggest you bring a sharpened blade if you are heading that direction.\n\nThe folks in that town look alright but something suspicious is going on in there.  Reports have been coming in that they are picking off our soldiers left and right.  We have had just about enough of that, so I need you to head down there and do a little cleaning house for us.\n\nTake down as many as you can and report back when you are done.", sourceObjective = "Commander Larmash has asked you to kill 14 villagers in Rustberg Village. Rustberg Village is just north of base camp, on the right side.", progress = "Did you find out what's up with that village?  Something seems off...", completion = "Told you that village was full of wackos.  Nice job clearing it out {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28687] = { id = 28687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teach A Man To Fish.... Or Steal", description = "Rustberg Village.  That place is a curse and a blessing for us, {name}.  I have no clue where bandits learned to fish as well as they do but I have no time to worry about that now.\n\nI need you to head down there and steal as many of their fish reserves as possible.  We have been living off scraps since we retook the island and this is our best chance at some solid food reserves.\n\nKeep an eye out for stealthers up there, reports have told us they are prevalent inside the village walls.", sourceObjective = "You must steal 22 Rustberg Seabass from Rustberg Village. The fish can be found on string stands at the docks, round back of the village. Rustberg Village is due north of base camp, on the right side.", progress = "Were you able to pull off the heist and get us some fish?", completion = "These fish will do nicely, {name}.  Keeping the troops fed and in good condition is our number one priority and you really came through for us here.", sourceObjectiveStatus = "unverified-source-field" }
quests[28688] = { id = 28688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Northern Stranglethorn Vale!", description = "All able bodied members of the Horde are hereby ordered to report to Commander Aggro'gosh at Grom'gol Base Camp. The commander requires your aid to keep the supply routes open and free of interference from the local inhabitants and the troublesome Alliance.\n\nTo reach Grom'gol, you can take the zeppelin Orgrimmar's eastern zeppelin tower or the one near Undercity.\n\nDestiny calls!", sourceObjective = "Report to Commander Aggro'gosh at Grom'gol Base Camp in the Northern Stranglethorn Vale.", completion = "At last, the Warchief's reinforcements have arrived.", sourceObjectiveStatus = "unverified-source-field" }
quests[28689] = { id = 28689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forgotten", description = "Many soldiers died on this island {name}.  It is only fair that we pay our respects to them in any way that we can.\n\nI need you to travel to Forgotten Hill, due west of here and release our brothers in arms' tortured souls away from this place.  Do be careful over there, reports of undead have been ongoing in the area.", sourceObjective = "Release the spirits of 6 tortured souls at Forgotten Hill. Souls can be channeled by touching your hands directly to the gravestones. Forgotten Hill is due west of here, past The Restless Front.", completion = "May their souls rest in peace.", sourceObjectiveStatus = "unverified-source-field" }
quests[28690] = { id = 28690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salvaging the Remains", description = "Forgotten Hill has been overrun with zombies and ghouls ever since we reclaimed this wretched isle.  We have tried to clear them out many times but they always seem to come back.\n\nOne of our lieutenants recommended taking the ghouls' bones when we kill them in hopes that they can't reincarnate overnight.  Think you can help us out with this one?", sourceObjective = "You need to recover 9 Cursed Femur bones from the ghouls that inhabit Forgotten Hill. Forgotten Hill is on the west side of the island, just past The Forgotten Front.", progress = "Were you able to recover the femur bones?  Better for you to try than me.", completion = "I didn't think you would be able to do it, {name}.  You are just full of surprises aren't you?", sourceObjectiveStatus = "unverified-source-field" }
quests[28691] = { id = 28691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Lieutenant Connor", description = "The first time I heard about Lt. Connor, I was just a young recruit in Ragefire Chasm.  None of us could believe he ended up here on Tol Barad.  Sadly, he still roams these wretched islands, wreaking havoc on our troops morale.\n\nI need you to put an end to his misery... and ours.", sourceObjective = "Find and kill First Lieutenant Connor at Forgotten Hill. You will find Forgotten Hill on the far west side of the island.", progress = "Is First Lieutenant Connor a goner?", completion = "Hey, you made it back alive!  Can't say you were the first one to try this task, but you are definitely the first one to make it back alive.", sourceObjectiveStatus = "unverified-source-field" }
quests[28692] = { id = 28692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magnets, How Do They Work?", description = "Getting useful machine parts out here on the island has been difficult, {name}.  We have been trying to repair the broken siege engines here in camp but we keep running out of useful parts.\n\nOur second regiment reported some wrecked out siege engines in a old battlefield to the west.  Maybe we could find some parts over there?\n\nYou are going to have trouble finding anything in that old battlefield so take this magnetized scrap collector and put it to some good use.", sourceObjective = "You have been tasked with recovering 7 pieces of Siege Engine Scrap. Use the Magnetized Scrap Collector in The Restless Front to find the scraps. The Restless Front is due west, just past the second bridge.", progress = "Did that magnet contraption actually work?", completion = "These parts will really help us out, {name}!  Who would have thought you can find stuff this useful in all that old junk?", sourceObjectiveStatus = "unverified-source-field" }
quests[28693] = { id = 28693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finish The Job", description = "We have been trying to collect useful scraps from the front all week.  Every time we gather a batch to bring back to camp, we get assaulted by the restless soldiers in the area.  Can you head over there and clear them out?", sourceObjective = "Kill 5 Restless Soldiers at the Restless Front. You can find the front on the west side of the island, just before Forgotten Hill.", progress = "Were you able to finish the job?", completion = "It's about time someone took those guys out.", sourceObjectiveStatus = "unverified-source-field" }
quests[28694] = { id = 28694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watch Out For Splinters!", description = "Have you been over to the Wellson Shipyard yet, {name}?  Best to stay away from there unless you have a good reason to venture in.  Unfortunately, that is exactly what I need you to do.\n\nYou see, we have been short on supplies ever since we recaptured the island.  That ghost ridden shipyard is overflowing with lumber but every time we send an escort to recover the lumber, they never make it back.\n\nCan you help us out?", sourceObjective = "Private Sarlosk has asked you to recover 15 pieces of Shipyard Lumber from the Wellson Shipyard. The lumber can be recovered from the ghosts in the shipyard or found lying around the premises. The shipyard can be found northwest of here, on the coast.", progress = "Did the ghosts scare you off?", completion = "I didn't think you would be able to do it, {name}.  You are just full of surprises aren't you?", sourceObjectiveStatus = "unverified-source-field" }
quests[28695] = { id = 28695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Foreman Wellson", description = "Foreman Wellson has been a pain in our side since we got here.  His shipyard holds a large amount of supplies that would be extremely useful to us... if we could get to them.\n\nHe keeps a close watch over his minions and makes it very difficult for us to get a foothold on the shipyard.  I need you to take out Wellson for good this time.  Be careful {name}, we have been receiving reports of dirty Alliance all around the area.", sourceObjective = "Kill Foreman Wellson at the Wellson Shipyard. The shipyard can be found north of here, on the western coast.", progress = "Were you able to \"take care of\" Foreman Wellson?", completion = "Great work {name}.  I will report your efforts to our highest in command immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[28696] = { id = 28696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombs Away!", description = "The Wellson Shipyard is constantly receiving supplies from offshore and we need to put a stop to it.  They have setup cannons along the docks for defense but if you can make it to them, we can use them to destroy their supply ships.\n\nHead down there and see what you can do.  Report back to me on your progress.", sourceObjective = "Destroy 10 Ghastly Supply Boats.", progress = "Did you take out the boats?", completion = "Great work on those supply ships, {name}!  We knew you would be good for somethin' around here.", sourceObjectiveStatus = "unverified-source-field" }
quests[28697] = { id = 28697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghostbuster", description = "See that hill with the towers to the northeast?  That's Largo's Overlook and it's not a fun place to set up camp next to.  We have been dealing with those spirits and spectres ever since we setup camp.\n\nCan you head up there and let them know we don't plan on leaving anytime soon?  A few good kills on their ranks should put them in line.\n\nThanks for your help on this, {name}.", sourceObjective = "Kill 14 ghosts of any type at Largo's Overlook, northeast of the Horde camp.", progress = "Who's afraid of ghosts?  Not me.  Well, maybe in the dark.", completion = "Great work, {name}!  We should not hear from the ghosts again anytime soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[28698] = { id = 28698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cannonball!", description = "Largo and his minions have been stealing our supplies ever since we setup camp here.  It's frustrating to say the least.\n\nWe have heard reports that he is stockpiling cannonballs in the towers overlooking the water up on his overlook.  Can you head up there and try to recover some of them for us?\n\n{name}, don't forget to keep a watch out for Alliance too.", sourceObjective = "You need to recover 4 Stacks of Cannonballs from Largo's Overlook for Private Sarlosk. You can find Largo's Overlook just northeast of the base camp.", progress = "Did you find the cannonballs?", completion = "Good job on the recovery effort {name}. These cannonballs should last us a while.", sourceObjectiveStatus = "unverified-source-field" }
quests[28699] = { id = 28699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Northern Stranglethorn Vale!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Lieutenant Doren at the Rebel Camp.\n\nYears after Colonel Kurzen's treachery against Stormwind, the truth of what happened remains a mystery. Aid the survivors in learning what became of the colonel. Travel south from Duskwood and follow the road west after crossing into the jungle to reach the Rebel Camp.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Lieutenant Doren at the Rebel Camp in the Northern Stranglethorn Vale.", completion = "Welcome to our camp, {class}, such as it is.", sourceObjectiveStatus = "unverified-source-field" }
quests[28700] = { id = 28700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Overlook Back", description = "There is only one way for us to take Largo's Overlook back.\n\nI think you know what we need to do {name}.  Largo is pretty paranoid these days so you should be able to find him on top of the tower, looking for his imaginary navy to finally arrive.", sourceObjective = "Private Sarlosk has asked you to kill Commander Largo at Largo's Overlook. The overlook is just northeast of the base camp.", progress = "Were you able to take out Largo?", completion = "Ha, we finally got Largo!  Nice one, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28701] = { id = 28701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of Harm's Way", description = "Luckily, when the infestation occured, no druids were slumbering in the western barrow den. It is still a sacred site to us, however, and its depths hold blessed relics kept there undisturbed for ages.\n\nWhile I am somewhat trusting of the goblin exterminators, I am also... familiar with the habits of their race. Please retrieve any relics you can find in the barrow den and bring them back to me so they are not damaged. They are within urns, nestled in the small alcoves throughout the den.", sourceObjective = "Retrieve 5 Starfall Relics from the Ban'Thallow Barrow Den.", progress = "I hope you found them intact...", completion = "They may not look like much to you, but these relics hold great value to the people of Starfall.  You are kind, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28702] = { id = 28702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: The Cape of Stranglethorn!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Bronwyn Hewstrike at the Explorers' League Digsite.\n\nThe Explorers' League expedition needs your help to safeguard its site and findings from marauding ogres. Travel south from Northern Stranglethorn Vale and follow the road to the Explorers' League Digsite.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Bronwyn Hewstrike at the Explorers' League Digsite on the Cape of Stranglethorn.", completion = "It's good to see you here, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28703] = { id = 28703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Step Into My Barrow", description = "I've still got no clue where all these bugs came from. My best guess is the cataclysm stirred up some underground nests we never knew about.\n\nNo use getting distracted with that when they need killing, though!", sourceObjective = "Kill 10 Coldlurk Creepers and 5 Coldlurk Burrowers.", completion = "Hey, nice work!\n\nIf you ever want to come back and kill some more bugs for absolutely no additional reward, please, feel free!", sourceObjectiveStatus = "unverified-source-field" }
quests[28704] = { id = 28704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: The Cape of Stranglethorn!", description = "All able bodied members of the Horde are hereby ordered to report to Sassy Hardwrench at Hardwrench Hideaway. She requires your help to deal with the pirates and naga who have overrun the jungle.\n\nTravel to Hardwrench Hideaway by heading south from Northern Stranglethorn and looking for the town southwest of the Gurubashi Arena.\n\nDestiny calls!", sourceObjective = "Report to Sassy Hardwrench at Hardwrench Hideaway on the Cape of Stranglethorn.", completion = "Welcome to Hardwrench Hideaway!", sourceObjectiveStatus = "unverified-source-field" }
quests[28705] = { id = 28705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Outland!", description = "All able bodied members of the Horde are hereby ordered to report to Lieutenant General Orion at the Stair of Destiny.\n\nYour skills are needed to fight the Burning Legion's presence on the shattered remnants of Outland.\n\nGo to Orgrimmar's Cleft of Shadow and use the portal near the mage trainers to reach the Blasted Lands, then travel through the Dark Portal itself to reach Hellfire Peninsula.\n\nDestiny calls!", sourceObjective = "Report to Lieutenant General Orion at the Stair of Destiny in Hellfire Peninsula.", completion = "Prepare yourself for battle. The Horde has need of you here.", sourceObjectiveStatus = "unverified-source-field" }
quests[28706] = { id = 28706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spray it Forward", description = "My fellow siblings are already further down in the den trying to deal with these bugs, and they're starting to get overwhelmed. I say it's time to gas the place.\n\nTake these fumigators. Don't go setting them off yourself; it takes a highly trained professional, and proper timing. Just find my sisters and pass them out.\n\nRemma should be positioned closest to the entrance. Head down the corridor and  keep to your right once you go down the ramp.", sourceObjective = "Bring the Box of Bugkill Fumigators to Remma Curtainfire inside the Ban'Thallow Barrow Den.\n\nProvided item:", completion = "We're bringing out the bug spray, eh? I guess it can't be helped.", sourceObjectiveStatus = "unverified-source-field" }
quests[28707] = { id = 28707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spray it Again", description = "I'm gonna start setting this up.\n\nNext one goes to Marcy, further down the den. Head down this corridor here and look for her in the next main chamber.", sourceObjective = "Bring the Box of Bugkill Fumigators to Marcy Curtainfire inside the Ban'Thallow Barrow Den.", progress = "Wasn't expecting to see a stranger down here!", completion = "Fumigators? From Rinno? Geez...", sourceObjectiveStatus = "unverified-source-field" }
quests[28708] = { id = 28708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Outland!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Commander Duron in Hellfire Peninsula.\n\nThe expeditionary forces require your help to overcome the demonic armies of the Burning Legion! Use the portal on the middle level of the tower in the Mage District to travel to the Blasted Lands, then travel through the Dark Portal to reach the Stair of Destiny in Outland.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Commander Duron at the Stair of Destiny in Hellfire Peninsula.", completion = "The expedition needs your help, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28709] = { id = 28709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Northrend!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Recruitment Officer Blythe at Valiance Keep in Borean Tundra.\n\nThe Valiance Expedition needs your help to keep the forces of the Scourge under control and safeguard civilized lands! Make your way to the Stormwind Docks and take the ship north to Valiance Keep.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Recruitment Officer Blythe at Valiance Keep in Borean Tundra.", completion = "The expedition needs your help, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28710] = { id = 28710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spray it One More Time", description = "You'd think Rinno could have sent more than a single {race} down here to give us a hand! That freeloader...\n\nI'm gonna set this up. Head north from this room through the corridor and look for Sana. She's probably gotten herself lost in the last chamber, so check the side passages once you get there.", sourceObjective = "Bring the Box of Bugkill Fumigators to Sana Curtainfire in the Ban'Thallow Barrow Den.", progress = "What're you doing here?", completion = "Rinno sent you! And you brought... fumigators? Ugh!", sourceObjectiveStatus = "unverified-source-field" }
quests[28711] = { id = 28711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Northrend!", description = "All able bodied members of the Horde are hereby ordered to report to the Warsong Recruitment Officer at Warsong Hold.\n\nThe Warsong Offensive needs your help to overcome the continued threat from the undead Scourge.\n\nTake the zeppelin to Warsong Hold from Orgrimmar's western zeppelin tower and present yourself to the recruitment officer.\n\nDestiny calls!", sourceObjective = "Report to the Warsong Recruitment Officer at Warsong Hold in Borean Tundra.", completion = "The Warsong Offensive could use more like you, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28712] = { id = 28712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enter the Dragon Queen", description = "Hello, {race}. I wish we could meet in more favorable circumstances. The world hangs by a thread, and all that the Titans have wrought may be in jeopardy.\n\nIt saddens me greatly, but my judgment is final. Deathwing - the horrific creature that was once the Earth Warder and once my friend - must be destroyed.\n\nI have prepared a site atop the Highlands, to the west of the Vermillion Redoubt, where I can bring about his end. Seek out the Circle of Life and speak with Lirastrasza within. I will join you there.", sourceObjective = "Seek out Lirastrasza at the Circle of Life in Twilight Highlands.", completion = "Hello again, {race}. I hear you were instrumental in our push toward Grim Batol - thank you!\n\nAlexstrasza has sanctified this ground in the hopes of luring Deathwing here. She'll perform a ceremony to lure him out... and then destroy him within this sacred circle.\n\nLet's hope her plan works.", sourceObjectiveStatus = "unverified-source-field" }
quests[28713] = { id = 28713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Balance of Nature", description = "Greetings, {name}. I am Ilthalaine. My purpose in Shadowglen is to train young {class}s like you and to ensure that the balance of nature is maintained.\n\nThe spring rains were particularly heavy this year, causing some of the forest's beasts to flourish while others suffered. Unfortunately, the nightsaber numbers grew too large, and they will devastate the other populations if they are not culled.\n\nJourney forth, young {class}, and thin saber populations so that nature's harmony will be preserved.", sourceObjective = "Kill 6 Young Nightsabers.", progress = "There is still work to be done, {name}. Return to me once you have thinned the nightsaber population.", completion = "You performed your duties well, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28714] = { id = 28714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Moss Corruption", description = "You seem to know what you're doing. Perhaps I can task you with something a little more important.\n\nAs you may well know, the corruption in Teldrassil was supposedly wiped away. Yet something lingers. The creatures have not calmed and all manner of problems still plague us.\n\nI need you to deal with the grellkin that have gathered to the west, and while you're there, I want you to search them for fel moss. This will help me determine from where this continuing corruption stems.", sourceObjective = "Collect 6 Fel Moss from the grellkin to the west of Ilthalaine.", progress = "Satisfy my suspicions, {name}. Bring to me fel moss from the grellkin.", completion = "Your service to the creatures of Shadowglen is worthy of reward, {name}.\n\nYou confirmed my fears, however. The grellkin are still tainted by fel moss, despite Teldrassil's blessing. Something sinister remains within the tree. I can only hope that the Gnarlpine tribe of furbolgs are free of the corruption, or we are still in grave danger.\n\nI will look into this further and contact those who might be of aid. Thank you, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28715] = { id = 28715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demonic Thieves", description = "Vicious little grell! They've been stealing from our foodstores again.\n\nIf you wouldn't mind lending a hand, they are sure to have my stolen bags within their camps to the west. I would be glad to reward you if you can bring them back to me.", sourceObjective = "Recover Melithar's Stolen Bags near the grellkin to the west.", progress = "I don't have any spare supplies for my customers until my stolen goods are recovered. Have you had any luck?", completion = "Elune be praised! And you as well, young {class}.\n\nThere are many young night elves in need of these, but I'd be more than happy to give you one of the bags as a reward. I'm sure it will come in handy.\n\nSafe travels to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[28716] = { id = 28716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Twilight Highlands!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to the throne room in Stormwind Keep.\n\nKing Wrynn requires a trustworthy and proven hero for a mission of the utmost importance.\n\nStormwind Keep can be found in the eastern portion of Stormwind City.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Speak with King Varian Wrynn at Stormwind Keep in Stormwind.", completion = "We are pleased that you have answered our summons, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28717] = { id = 28717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Twilight Highlands!", description = "All able-bodied members of the Horde are hereby ordered to report to Garrosh Hellscream in Grommash Hold.\n\nThe Warchief requires your help to prepare for the glorious assault on the Twilight Highlands and our dual enemies, the Alliance and Twilight's Hammer.\n\nMeet with the Warchief in Grommash Hold at the center of Orgrimmar's Valley of Strength.\n\nDestiny calls!", sourceObjective = "Report to Garrosh Hellscream at Grommash Hold in Orgrimmar.", completion = "Soon, the assault on the Twilight Highlands will begin, and I intend for you to be a part of it.", sourceObjectiveStatus = "unverified-source-field" }
quests[28718] = { id = 28718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where There's Smoke, There's Delicious Meat", description = "Say there, {class}... do you like meat?  Even better, do you like money?\n\nI got a second cousin who's making a killing in the frozen meats business.  He's set up a smoking pit up north, and he's looking for help hunting all the dangerous beasties that always tend to taste so good.\n\nCarnivores pay well, friend.  I'm too heavily invested here in this barrow den - what was I thinking? - so I might as well pass the tip on to a helpful {race} like yourself.\n\nHis name's Jez.  Head northeast, and look for the smoke!", sourceObjective = "Find Jez Goodgrub at Goodgrub Smoking Pit in Winterspring.", completion = "Look around you; you're looking at the largest goblin-owned hunting reserve in Kalimdor! I've got the licenses to shoot and eat everything that walks on the snow from here to Everlook... and lemme tell you, they're good eatin'!", sourceObjectiveStatus = "unverified-source-field" }
quests[28719] = { id = 28719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Gamy", description = "Many find the meat of the Shardtooth bears to be too gamy for their taste. I disagree, though I'm not one to judge the tastes of others.\n\nThe Shardtooth Maulers, however - their brown-furred cousins, to the south - have much more tender flesh, particularly in their paws. And I've heard that the snout is also considered a delicacy.\n\nContinue your hunt, {name}. Let's see if you can bag those maulers for ol' Francis.", sourceObjective = "Kill 15 Shardtooth Maulers.", completion = "<Francis smacks his lips.>\n\nYou've got to try some of this, {name}.  These maulers are perfectly tenderized... possibly because of the pummeling you delivered.", sourceObjectiveStatus = "unverified-source-field" }
quests[28722] = { id = 28722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yetiphobia", description = "It's all ready, {name}!\n\nNow, I told my friend Legacki that I have a surprise for her. This is where you come in!\n\nI'm going to give you my mechanical yeti, and you'll get the honor of using it to surprise her. She's just on the other side of Everlook, near the inn.\n\nGo up to her and turn the yeti on... I'll be watching from here!", sourceObjective = "Scare Legacki with Umi's Mechanical Yeti.", progress = "She'll never expect it!", completion = "Hah! She'll think twice before making fun of my ideas again!\n\nThanks for your help, {name}. I couldn't have had so much fun without you!", sourceObjectiveStatus = "unverified-source-field" }
quests[28723] = { id = 28723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priestess of the Moon", description = "Now that you're practiced in your new ability, perhaps you'd be willing to aid us in further pursuing the corruption haunting Shadowglen.\n\nDentaria Silverglade, Priestess of the Moon, has offered to aid us. You should find her between the two pools just north of our great tree. Circle around the tree to reach her and offer her any help that you can, young {class}.", sourceObjective = "Speak to Dentaria Silverglade between the two pools in the center of Shadowglen.", completion = "It is good that you've come. It seems your training progresses quickly.", sourceObjectiveStatus = "unverified-source-field" }
quests[28724] = { id = 28724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iverron's Antidote", description = "Our friend Iverron has fallen to poison from the nearby webwood spiders. I can tend to him to keep his state from deteriorating, but I need someone to gather an ingredient to prepare him an antidote.\n\nAll around the ponds you should find Moonpetal Lilies. These flowers have great healing properties, and I can use them with the ingredients I already have to restore Iverron to better health.\n\nWould you gather them for me?  There should be many just in sight of here, near the water's edge.", sourceObjective = "Collect 7 Moonpetal Lilies.", progress = "Our dear friend is not doing well, even with my mending. Have you brought the supplies I require?", completion = "These will do perfectly. Thank you, {name}. Your swiftness is appreciated.", sourceObjectiveStatus = "unverified-source-field" }
quests[28725] = { id = 28725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Woodland Protector", description = "I must ask something more dangerous of you. Strange news has traveled to me through the whisperings of the forest spirits. The mysterious woodland protector, Tarindrella, has returned to Shadowglen again.\n\nThe dryad's presence has not been felt in the forests since before the blessing of Teldrassil. Something is surely amiss if she has journeyed back to this land.\n\nSeek out Tarindrella in the Shadowthread cave to the north. It is dangerous, but we will be prepared with this antidote just in case.", sourceObjective = "Seek out the dryad known as Tarindrella within the Shadowthread Cave at the northern end of Shadowglen.", completion = "I see you found me, young {race}.  Dentaria was wise to have sent you.", sourceObjectiveStatus = "unverified-source-field" }
quests[28726] = { id = 28726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Webwood Corruption", description = "I'd hoped to never return to Teldrassil for such grim business. I'd hoped that its corruption had been wiped away completely.  Something foul lingers.\n\nThese spiders suffer much more deeply from the corruption than the other nearby wildlife. They are becoming a danger to your people and a danger to the forest. We must thin their numbers, but more importantly, we need to find the source of the corruption that plagues them.\n\nI will come with you and aid you in this.", sourceObjective = "Kill 12 Webwood Spiders.", progress = "This is grim work. It pains me to have to inflict such violence on creature of the forest, corrupt or not.", completion = "This corruption these spiders suffer from is not simply surface deep. It cannot be magic or subtle malintent. It is bred into them.\n\nIt seems our next task is clear.", sourceObjectiveStatus = "unverified-source-field" }
quests[28727] = { id = 28727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vile Touch", description = "If these spiders are born with corruption in their veins, then their broodmother must be at the root of this evil.\n\nLet us make our way to the far north end of the cave and seek out Githyiss the Vile. The answers we seek lie with her.", sourceObjective = "Kill Githyiss the Vile at the northen end of the Shadowthread Cave.", progress = "I adore these forests. I want to see the corruption purged from them completely. When next I return, I want to do so with a lighter heart.", completion = "Githyiss and her brood were being corrupted by this totem. This is a furbolg totem.\n\nThis is very troubling indeed. This means the Gnarlpine are still a danger to these forests. We let our guard down too soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[28728] = { id = 28728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signs of Things to Come", description = "I will pursue the trail of the Gnarlpine and track this corruption to its source. If you ever encounter Athridas Bearmantle in Dolanaar, he knows intimately of the problems that plague this forest, and he can direct you on how to help further.\n\nI'm sure we will meet again with time. Perhaps you can aid me in dealing with the source of this corruption once I locate it. For now, I will take you back to Dentaria so that you may finish your training. Thank you for all that you have done, {name}.", sourceObjective = "Speak to Dentaria Silverglade between the pools in northern Shadowglen.", completion = "You've returned! It's good to see you. It seems you've dealt with the source of much of the corruption in Shadowglen.\n\nTeldrassil still suffers and will need attention, but we can afford a moment or two for you to finish your training here in Shadowglen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28729] = { id = 28729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teldrassil: Crown of Azeroth", description = "As part of a ritual to complete your training here in Shadowglen, you must learn about our recent history.\n\nThere is a task you must perform. Go to the moonwell to our northeast and retrieve a phial of its water. While there, you will witness a glimpse of our magics and learn of our past.\n\nWhen you are done there, bring the water back to me, and I will direct you further.", sourceObjective = "Fill the Crystal Phial at the moonwell in northeast Shadowglen.", progress = "Our recent history is fraught with strife and violence. There is still much with which we must come to terms.", completion = "Well done, {name}. You have one task left for you before you depart Shadowglen for the open wilds of Teldrassil.", sourceObjectiveStatus = "unverified-source-field" }
quests[28730] = { id = 28730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Precious Waters", description = "Tenaron Stormgrip oversees all that happens in this glade. He presides at the top of Aldrassil.\n\nIf you look to your south, you will see the underside of the ramp that leads up to him. Ascend this ramp and complete your training.\n\nIt was wonderful to have met you, {name}. I swell with pride knowing that among young night elves, there are some so selfless and full of life as you are. You will do great things for our people. You will do great things for this world.\n\nUntil we meet again.", sourceObjective = "Bring the filled crystal phial to Tenaron Stormgrip at the top of Aldrassil in Shadowglen.", progress = "The moonwells hold the waters of the Well of Eternity, the ancient source of magic that has wrought so many horrors upon our world.\n\nThe druids take advantage of its properties, the Sentinels revere the wells as shrines to Elune, and now even the returning Highborne look to the wells longingly.", completion = "So you have heard the first part of the aftermath of the Battle of Mount Hyjal. There is much more for you to learn and the task you have begun here will continue through the rest of your journey through Teldrassil and into Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[28731] = { id = 28731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teldrassil: Passing Awareness", description = "While there is more I could speak to you of the moonwells and of Teldrassil, I must send you along. Corithras Moonrage will be expecting you. I have poured the phial of water you brought to me into this vessel to bring to him.\n\nSeek out Corithras. You will find him at the moonwell in Dolanaar. Follow the road south from Aldrassil out of Shadowglen, and continue to follow the cobblestones as the road turns west.\n\nMind you stay on the road though, {name}. There are dangerous beasts in the forests of late.", sourceObjective = "Bring the Partially Filled Vessel to Corithras Moonrage in Dolanaar.", progress = "Greetings, {class}. For what purpose do I owe the pleasure of our meeting?", completion = "Ah, I see. You were sent by Tenaron. Well then, it would seem we have much to talk about, much to do.\n\nBefore we get to the task at hand, you should take in the lesson of this moonwell.", sourceObjectiveStatus = "unverified-source-field" }
quests[28732] = { id = 28732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Can Only Mean One Thing...", description = "Raz and I were enlisted by the Guardians of Hyjal to investigate the re-emergence of Ragnaros into our world. Let me go ahead and confirm that he is back and he is angry! We also have evidence that these Twilight's Hammer cultists are moving elementals from here to Blackrock Caverns, over in the Eastern Kingdoms.\n\nRaz and I were about to head over there to investigate. We've got room for another in the mole machine if you're interested. Just meet us on the inside and we'll begin our journey.", sourceObjective = "Take Pip's Mole Machine to Blackrock Mountain.", progress = "HELP! HELP!", completion = "Oh dear, Raz has been captured! As soon as we entered a dozen cultists and some big fat ogre jumped us. I ran while Raz tried to fight them off. We need to save him, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[28733] = { id = 28733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basic Botany", description = "HELP! HELP! Crazed undead are attacking my farm! That psycho warden over at the Sludge Fields is probably responsible for this mess. Help me fight off the zombies!", sourceObjective = "Survive a Massive Wave of Zombies.", completion = "PHEW! That was close! You're a real natural with these plants, {class}. You know, I brought the seeds here with me from Lost Isles. I figure once I get them all figured out I'll make a fortune in the deadly flower business!\n\nWha... LOOK! MORE ARE COMING!", sourceObjectiveStatus = "unverified-source-field" }
quests[28734] = { id = 28734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Favor for Melithar", description = "You should speak with Melithar. I believe he had some troubles with the grell already.\n\nI expect he can offer you a well needed place to store more of your goods should you aid him.", sourceObjective = "Speak to Melithar Staghelm in Shadowglen.", completion = "Ilthalaine sent you? He was wise to do so. I am indeed in need of help.", sourceObjectiveStatus = "unverified-source-field" }
quests[28735] = { id = 28735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Chamber of Incineration!", description = "It was an ambush, {name}! As soon as we walked in a super-fat ogre named Rom'ogg Bonecrusher attacked us! Raz bravely defended me while I ran off to hide. I watched as they beat him unconscious and then dragged him to a place the fat one called the \"Chamber of Incineration.\" I think it's just down the hall across the bridge.\n\nI'm too scared to go any further. Take my all-purpose diving helm and search for Raz. I'll communicate with you through the helm.\n\nAnd if you find that ogre, kill him!", sourceObjective = "Kill Rom'ogg Bonecrusher.", progress = "<Finkle's helm crackles with static.>", completion = "<Pip's helm crackles with static.>\n\nRAZ! What have they done to him!? FOLLOW HIM!", sourceObjectiveStatus = "unverified-source-field" }
quests[28736] = { id = 28736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire From the Sky", description = "The remnants of Schnottz's organization persist here on the Maker's Ascent, making the region deadly to any who draw near.\n\nThere's plenty of ammunition, but without a good spotter, I'm just firing blind.\n\nHop in and give me a hand here. Those soldiers won't know what hit them!", sourceObjective = "Board the Confiscated Artillery and use it to kill 100 Schnottz Infantrymen.", progress = "It's a target-rich environment, {class}.", completion = "The enemy on Maker's Ascent remain a threat, but with your help we've dealt a serious blow to their numbers and their morale.", sourceObjectiveStatus = "unverified-source-field" }
quests[28737] = { id = 28737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Is This Place?", description = "<Pip's helm gives you a slight jolt.>\n\nWhat is this place? It looks like they're doing something terrible to that nether dragon. The energy is being siphoned from the creature into that lady! We need to stop this ritual!\n\nKill Corla to get past this hall!", sourceObjective = "Kill Corla, Herald of Twilight.", progress = "<Finkle's helm crackles with static.>", completion = "<Pip's helm crackles with static.>\n\nWe haven't got much time. Raz looked injured. If we get to him in time there might be a chance that I can turn him back into a regular orc!\n\n<You feel a sharp pain in the back of your head and hear the jingling of coins.>\n\nSorry about that. I figured I'd send through some gold - for your troubles and all that...", sourceObjectiveStatus = "unverified-source-field" }
quests[28738] = { id = 28738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Forge", description = "<Pip's helm hums with energy.>\n\nDamn it! Raz won't stop! It's as if he were possessed with a burning vengeance for all things Twilight! It looks like if we're going to get past this room and catch up with Raz we'll need to take out the Twilight armorer, Karsh Steelbender. Kill him quick, {name}.", sourceObjective = "Kill Karsh Steelbender.", progress = "<Pip's helm crackles with static.>", completion = "<Pip's helm crackles with static.>\n\nThat should put a stop to their armory - at least for now.\n\nRaz ran off across the ramp on the other side of the forge. GO GO GO!", sourceObjectiveStatus = "unverified-source-field" }
quests[28740] = { id = 28740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do My Eyes Deceive Me?", description = "<Pip's helm explodes with the sound of a loud girlish scream.>\n\nIT CAN'T BE! I... I was stuck inside one of those beasts for the better part of a month. Yes, literally stuck inside its stomach. If it weren't for my suit and the all-purpose helm I'd have died a fiery death! And look at that, it's had a litter of pups!\n\nY... You gotta stop that thing, {name}! We can't let it or its pups make it out of here alive!", sourceObjective = "Kill Beauty.", progress = "<Finkle's helm crackles with static.>", completion = "<Pip's helm crackles with static.>\n\nPhew... That's one less thing I'll need to worry about if we ever make it out of this place.", sourceObjectiveStatus = "unverified-source-field" }
quests[28741] = { id = 28741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ascendant Lord Obsidius", description = "<Pip's helm buzzes.>\n\nGOOD GOLLY! Look at this place! A... Are those Deathwing's claw marks on the ceiling?! And what's that creature in the center of the chamber?\n\nI don't see Raz anywhere. Let's take care of this monster and find Raz!", sourceObjective = "Kill Ascendant Lord Obsidius.", progress = "<Finkle's helm crackles with static.>", completion = "Poor Raz. He was the best friend a gnome ever had. At least we avenged his death and cleared out this hellish cavern!", sourceObjectiveStatus = "unverified-source-field" }
quests[28742] = { id = 28742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shy-Rotam", description = "Time for the big kill, pal! Shy-Rotam lurks in the north, the largest frostsaber of them all.\n\nYou should feel honored. There's no fiercer game for a hunter to match their skills against... and if you saw the cash I'm being offered by gourmands that want a piece of this fellow, your eyes would pop out!\n\nOnce you've got her, head on back to camp. Don't want to totally exhaust our frostsaber population in one day...", sourceObjective = "Slay Shy-Rotam.", completion = "Amazing, kid. You're a cut above! I went through about five different contracted hunters trying to get that cat.\n\nWell, we found two of them after the Captain got the corpse, but let's not dwell on that...", sourceObjectiveStatus = "unverified-source-field" }
quests[28743] = { id = 28743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tailgunner!", description = "You up for a little hunting, {name}?\n\nHop in! I'll fly, you shoot!", sourceObjective = "Shoot down 15 Schnottz Aces.", sourceObjectiveStatus = "unverified-source-field" }
quests[28744] = { id = 28744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghouls Hate My Grains", description = "You're a pro at this, {name}! A regular junior botanist! Listen, I've got a new seed to try called the rocknut. Use it to block the undead. Just drop it down and they'll stop dead in their tracks. Undead are so stupid!\n\nLet's give it a try!", sourceObjective = "Survive 2 Massive Waves of Zombies.", completion = "I think that made Stillwater angry. He's sending the heavy-hitters after us now. No time to lose, friend, let's go!", sourceObjectiveStatus = "unverified-source-field" }
quests[28745] = { id = 28745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Screechy Keen", description = "Them smaller owls are sure tasty, but Goodgrub says there's even bigger ones further south. Screechers, the folk around here call 'em... they make a heck of a noise when you tussle with them!\n\nBut he says they're the best owls he's ever tasted or sold, and I believe him. Why don't you go rustle up some of those for us while I keep arguin' with Francis here?", sourceObjective = "Slay 15 Winterspring Screechers.", sourceObjectiveStatus = "unverified-source-field" }
quests[28746] = { id = 28746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Penetrating Their Defenses", description = "Here we go, {name}!\n\nJust beyond that door lies the control room.\n\nI'll just run in, disable the reorigination mechanism, and then we all go home. Nice an' easy.\n\nYe see, <lad/lass>, it's this level of preparation that separates yer true archaeologist from yer average treasure hunter.\n\nNo sense in stirring up the beasties if ye don't have to. Just makes a mess a' things...", sourceObjective = "Gain entry to the Titan Control Room.", progress = "What is it, {name}?", completion = "Well, I've got bad news and I've got...\n\nNo, scratch that. There only be bad news.", sourceObjectiveStatus = "unverified-source-field" }
quests[28747] = { id = 28747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Someone Setup the Pumpkin Bomb", description = "You ever seen one of these?\n\n<Brazie pulls out a pumpkin.>\n\nThis ain't no ordinary pumpkin, friend. See, once you plant it they'll lay in wait until a zombie shows up and then KABLOOEY! Zombie guts all over the place. Let's go!", sourceObjective = "Survive 2 Massive Waves of Zombies.", completion = "D... Do you hear that rumblin'? I think Stillwater is comin'! HOLY MOLY LOOK OUT!", sourceObjectiveStatus = "unverified-source-field" }
quests[28748] = { id = 28748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lawn of the Dead", description = "IT'S STILLWATER! HE'S ALMOST HERE! It's going to take everything that we've got to beat him! Let's do this!", sourceObjective = "Defeat Warden Stillwater.", completion = "I can't believe we defeated him, {name}! That was the toughest fight yet, but there are still hundreds of crazed zombies roaming around Hillsbrad. We'll need to stay alert.", sourceObjectiveStatus = "unverified-source-field" }
quests[28749] = { id = 28749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Andorhal", description = "We just received a gryphon from the plaguelands, bearing news.  It doesn't sound good.\n\nThe city of Andorhal is in the middle of a three-way war between the Forsaken, the Alliance, and the Scourge.  King Wrynn has rolled the dice and sent a death knight to lead the charge for his cause, but I'm sure he can use all the help he can get.\n\nThey specifically asked for an Alliance {class} to participate in some specialized missions.  If you accept the charge, speak to me again and I will prepare a portal.", sourceObjective = "Speak with War-Mage Erallier to be teleported to Andorhal in Western Plaguelands. Then report to Thassarian within Andorhal.", completion = "It's about time you arrived, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28750] = { id = 28750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Andorhal", description = "We just received a windrider from the plaguelands, bearing news.  It doesn't sound good.\n\nThe city of Andorhal is in the middle of a three-way war between the Forsaken, the Alliance, and the Scourge.  It sounds like Sylvanas has made her move, and to make matters interesting, she's put Koltira Deathweaver, the death knight, in command.\n\nThey specifically asked for a Horde {class} to participate in some specialized missions.  If you accept the charge, speak to me again and I will prepare a portal.", sourceObjective = "Speak with Arcanist Arman to be teleported to Andorhal, in the Western Plaguelands. Then report to Koltira Deathweaver within Andorhal.", completion = "It's about time you arrived, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28751] = { id = 28751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tending the Garden", description = "Even though we beat Warden Stillwater, his zombies still roam the countryside. Look there, another wave is approaching! Help me fight them off, old buddy! Let's go!", sourceObjective = "Survive 2 Massive Waves of Zombies.", completion = "That'll keep 'em out for today, but I know they'll be back tomorrow. Hopefully you'll be around to help me.", sourceObjectiveStatus = "unverified-source-field" }
quests[28752] = { id = 28752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unstoppable Onslaught", description = "See how long you can last! Hold off at least 10 waves and I'll give you some coin." }
quests[28753] = { id = 28753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doing it the Hard Way", description = "Blast it all!\n\nSomeone's gone and corrupted the entire system! There be no way fer me ta access the main repository from this console.\n\nWe're gunna hafta do this the hard way, <lad/lass>. I hope you an' yer friends here are up to a fight.\n\nThere be four guardians on the upper level of this place. I won't be able ta utilize these discs 'til they be... uhh, offline, shall we say.", sourceObjective = "Brann Bronzebeard wants you to kill Isiset, Ammunae, Setesh, and Rajh.", completion = "Arrite, then.\n\nLet's deposit these discs and be done with this!", sourceObjectiveStatus = "unverified-source-field" }
quests[28755] = { id = 28755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Annals of the Silver Hand", description = "Do you know who the Knights of the Silver Hand were? They were the original paladins of the Light, and from their ranks came knights who would later join the Argent Dawn or the Scarlet Crusade. Though many have gone astray, they still possess valuable relics of the Silver Hand.\n\nDeep in Stratholme, under the watchful eye of Instructor Galford, volumes of the Annals of the Silver Hand survive. Any volumes you could recover would be a fitting addition to the rededicated Light's Hope Chapel.", sourceObjective = "Recover a lost volume of the Annals of the Silver Hand from Stratholme.", progress = "Have you recovered any of the lost histories of the Silver Hand?", completion = "This is indeed one of the lost volumes! Tyrosus will be most pleased when he learns of your find.", sourceObjectiveStatus = "unverified-source-field" }
quests[28756] = { id = 28756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aberrations of Bone", description = "In life, my brothers and I fought against all the forces of the Scourge, but none were so reviled as the necromancers. It was not enough for them raise our dead comrades and send them against us; no, they created twisted golems of bone with scythes for hands.\n\nThese aberrations slew many of my brothers, and yet we could not destroy them all. I ask you, {name}, to carry on the task of the fallen. Venture into the Ossuary of Scholomance and slay the largest and most dangerous of these abominable creatures.", sourceObjective = "Kill Rattlegore in the Ossuary of Scholomance.", completion = "Your deeds do honor to those who fell in battle defending this hallowed ground.", sourceObjectiveStatus = "unverified-source-field" }
quests[28757] = { id = 28757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beating Them Back!", description = "So you're the new recruit from Stormwind, eh? I'm Marshal McBride, commander of this garrison. Glad to have you on board...\n\n<McBride looks through some papers.>\n\n{name}. It is {name}, right?\n\nYou've arrived just in time. The Blackrock orcs have managed to sneak into Northshire through a break in the mountain. My soldiers are doing the best that they can to push them back, but I fear they will be overwhelmed soon.\n\nHead northwest into the forest and kill the attacking Blackrock worgs! Help my soldiers!", sourceObjective = "Kill 6 Blackrock Battle Worgs.", completion = "You've bought us a little time, {name}, but we've got even bigger problems to deal with now.", sourceObjectiveStatus = "unverified-source-field" }
quests[28758] = { id = 28758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of Life and Death", description = "Alexstrasza and Deathwing have taken into the skies over Grim Batol! Her plan unravels - the Dragon Queen is outside the Circle of Life she prepared earlier. We'll need to support her with everything we've got.\n\nHurry! Climb aboard one of the Vermillion Vanguard behind me.\n\nIf we find any Twilight Drakes aiding Deathwing, we will need to kill them off. Mount up, quickly!", sourceObjective = "Mount a Vermillion Vanguard. Slay 8 Twilight Shadowdrakes.", progress = "The battle continues, {name}.", completion = "Thanks to your quick action, the Dragon Queen still lives. She is being brought back to Wyrmrest to recover.\n\nBut the battle wasn't a complete failure. Deathwing was gravely wounded. I suspect he will go into hiding to recuperate. Alexstrasza has bought us time to strike!", sourceObjectiveStatus = "unverified-source-field" }
quests[28759] = { id = 28759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lions for Lambs", description = "The invading orcs aren't fools. They are sizing us up, making sure that when they attack it will be to their advantage.\n\nIn the forest, to the northwest, are Blackrock spies. They peer at us through spyglasses, watching our every move - waiting. I want you take the fight to them!\n\nKill the Blackrock spies! We must show them that we know they are watching us and that we are prepared!", sourceObjective = "Kill 8 Blackrock Spies.", completion = "Excellent work, {name}. You've turned out to be quite an asset to this garrison. It's time for you to train!", sourceObjectiveStatus = "unverified-source-field" }
quests[28760] = { id = 28760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance for Orsis", description = "The great city of Orsis was attacked by the armies of air.\n\nWe were taken prisoner.  We were the lucky ones.\n\nMost died, trapped beneath the choking desert sands.\n\nAsaad, Al'Akir's caliph, ordered the attack... and he must pay with his life.", sourceObjective = "Slay Asaad.", progress = "Is it done, {name}?", completion = "Blessings upon you.  Please accept this as a token of my gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[28762] = { id = 28762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beating Them Back!", description = "So you're the new recruit from Stormwind, eh? I'm Marshal McBride, commander of this garrison. Glad to have you on board...\n\n<McBride looks through some papers.>\n\n{name}. It is {name}, right?\n\nYou've arrived just in time. The Blackrock orcs have managed to sneak into Northshire through a break in the mountain. My soldiers are doing the best that they can to push them back, but I fear they will be overwhelmed soon.\n\nHead northwest into the forest and kill the attacking Blackrock worgs! Help my soldiers!", sourceObjective = "Kill 6 Blackrock Battle Worgs.", progress = "Have you beaten back the Blackrock battle worgs?", completion = "You've bought us a little time, {name}, but we've got even bigger problems to deal with now.", sourceObjectiveStatus = "unverified-source-field" }
