quests[28768] = { id = 28768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterspring!", description = "Donova Snowden, dwarf woman, is friend of the Timbermaw.\n\nWe trade firewater.\n\nShe is at Frostfire Hotsprings, to the east, through our cave.\n\nShe needs help to beat up the Winterfall furbolg.  Maybe you will help her.", sourceObjective = "Report to Donova Snowden at Frostfire Hot Springs in Winterspring.", completion = "Thank goodness you're here. I've discovered the secret of the fierce Winterfall furbolg.", sourceObjectiveStatus = "unverified-source-field" }
