quests[28824] = { id = 28824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wayward Child", description = "One of my children is not with me, {name}.\n\nHe stayed behind with the Twilight's Hammer at the Stonecore deep within the Temple of Earth.\n\nI sent my other children to free him from the dark magic that was surely keeping him from returning here, but... no such magic was placed upon him.\n\nGo into the Stonecore and destroy Ozruk.  He must be reclaimed by the earth.", sourceObjective = "Slay Ozruk.", completion = "<Therazane's eyes appear slightly more crystalline than you recall.>\n\nOzruk has been reclaimed by the earth.\n\nTake your reward and leave me be, {name}.  I wish to be left alone.", sourceObjectiveStatus = "unverified-source-field" }
quests[28825] = { id = 28825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Personal Summons", description = "<An unfamiliar feeling wells up from deep within you, flooding your mind with thoughts and images.>\n\nHear my words, {name}.\n\nOur world finds itself in the grip of a terrible crisis.\n\nI call upon you to lend your aid in this desperate hour.\n\nI am Naraat.\n\nSeek me out at once, and your calling shall be revealed.\n\nI await you at the Eastern Earthshrine in Stormwind City.", sourceObjective = "Speak to Naraat the Earthspeaker in Stormwind.", completion = "May your sense of honor and duty serve Azeroth well, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28826] = { id = 28826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of the Storm", description = "Greetings, hero of Azeroth.\n\nWe of the Earthen Ring know you by name, {name}.\n\nYour exploits and accomplishments are many. Azeroth already stands in your debt, and yet again she is in need of her heroes.\n\nI am but a messenger. A powerful presence seeks audience with you.\n\nPeer into the Waters of Farseeing and behold the dilemma of our world.", sourceObjective = "Naraat the Earthspeaker wants you to look into the Waters of Farseeing.", progress = "Yes, {class}?", completion = "Now that your eyes have seen the truth, where will you choose to serve?", sourceObjectiveStatus = "unverified-source-field" }
quests[28827] = { id = 28827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Depths", description = "The Earthen Ring has identified the watery realm of Vashj'ir as a source of the adversary's destructive energies.\n\nIt is still uncertain what dangers might be faced there, so any information you could gather would be of great value.\n\nThe Alliance is sending warships to the region as we speak. To gain passage, travel northwest of Stormwind and speak to Recruiter Burns at Stormwind Harbor.\n\nMay the spirits guide you, {name}.", sourceObjective = "Speak with Recruiter Burns at Stormwind Harbor in Stormwind City.", completion = "All of our war ships are off fighting the Horde. You'll have to take the mercenary ship.", sourceObjectiveStatus = "unverified-source-field" }
quests[28828] = { id = 28828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Gotta Have Eggs", description = "I don't have a very discerning palate, but even I can't stand the taste of those chimaeras that you'll find around here.  Their eggs, however, are a different story.\n\nChimaera eggs are the richest, most buttery eggs you'll find this side of Orgrimmar.  Way better than boring owl eggs, and not as sulfurous as those weird wildkin eggs.\n\nI'll take as many of them as you can gather.  Head northeast, and look for their nests in the snow.", sourceObjective = "Obtain 40 Chillwind Eggs.", progress = "Mmmm....", completion = "Nice. Eggs.\n\nThese will go great with a little bear bacon.  Hey Francis, got any bear meat left over?", sourceObjectiveStatus = "unverified-source-field" }
quests[28829] = { id = 28829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Razor Beak and Antlers Pointy", description = "What happened to me, you ask?  Listen, {class}, and listen well, for my tale is one of tragedy...\n\nI was sent here to Owl Wing Thicket to find some relics.  I only made it this far before I was overwhelmed by a flurry of wings and talons.\n\nHow they roared and pecked, {class}!\n\nI now lay here, a broken orc, with nothing but vengeance on my mind. Please, {class}, if you have any sense of honor, you will go into Owl Wing Thicket and help me regain mine.", sourceObjective = "Slay 12 Owlbeasts in Owl Wing Thicket.", progress = "They came at me two at a time, {class}.  I stood no chance.", completion = "My honor is restored.\n\nPartially.\n\nMy tale continues, {class}, for I have left portions of my honor elsewhere in this forest.\n\nIt has not been a very easy journey for me.", sourceObjectiveStatus = "unverified-source-field" }
quests[28830] = { id = 28830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chips off the Old Block", description = "My mysterious benefactors gave me more than one task. The second task took me farther south, to the Frostwhisper Gorge. I was surprised to learn that the gorge's bridge had been broken in two, preventing land travel from one side to the other.\n\nIn addition, the juvenile Frostmaul tumblers were separated from their stronger adult parents. I thought that I could defeat them in battle.\n\nI was incorrect. I was forced to run away in shame.\n\nTeach these tumblers a lesson, {name}. Fight them, and win.", sourceObjective = "Slay 8 Frostmaul Tumblers.", completion = "Be glad that the adult giants are trapped on the other side of that gorge. They are far hardier than these tumblers you fight.\n\nI feel rejuvenated by your courage, {class}. Perhaps all hope is not lost after all...", sourceObjectiveStatus = "unverified-source-field" }
quests[28831] = { id = 28831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Damn You, Frostilicus", description = "The Frostmaul giants wouldn't have been a problem if it weren't for that damned Frostilicus. When the ground shook and the bridge broke, he and his fellow water elementals seeped out of the earth and took over the bottom of Frostwhisper Gorge, forcing the giants out.\n\nDamn you, Frostilicus!\n\nYou would do me a great honor if you would send him back into the ground, {class}. You will find him to the south, at the bottom of the gorge.", sourceObjective = "Slay Frostilicus.", completion = "If I survive my wounds, I will always remember your name, {class}.\n\nWhenever the wind whistles through the trees, I will always hear your name.\n\nThank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[28832] = { id = 28832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Shores", description = "Right then, just hop in the seaplane behind me and I'll fly yeh to the Highlands.\n\nWe're to report to a feller named \"Lieutenant Fawkes.\" I've promised the King we'd get there lickety-fast, so I took the liberty of ditchin' any excess weight. Like seatbelts. Parachutes. Maps. Stabilizers. Landing gear.\n\nI never actually \"land\" these things anyways.", sourceObjective = "Speak with Lieutenant Fawkes at Highbank in Twilight Highlands.", completion = "You two are the last thing I expected to see fall from the sky. Highbank is under attack!", sourceObjectiveStatus = "unverified-source-field" }
quests[28833] = { id = 28833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue the Earthspeaker!", description = "Good! You've brought allies.\n\nYou must hurry if we are to rescue Erunak.\n\nFight your way through Neptulon's halls. Find the shaman and free him from these worms... if he still lives.\n\nDon't worry about them coming up from behind you. Nothing's making it past me!", sourceObjective = "Rescue Erunak Stonespeaker.", progress = "I thank you, my friend.", completion = "What is this? You... rescuing me?\n\n<Erunak smiles at you.>\n\nThis will take some getting used to.", sourceObjectiveStatus = "unverified-source-field" }
quests[28834] = { id = 28834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue the Earthspeaker!", description = "Good! You've brought allies.\n\nYou must hurry if we are to rescue Erunak.\n\nGo now. Fight your way through Neptulon's halls. Find the shaman and free him from these worms... if he still lives.\n\nDon't worry about them coming up from behind you. I'll see that nothing makes it past me!", sourceObjective = "Rescue Erunak Stonespeaker.", progress = "I thank you, my friend.", completion = "What is this? You... rescuing me?\n\n<Erunak smiles at you.>\n\nThis will take some getting used to.", sourceObjectiveStatus = "unverified-source-field" }
quests[28836] = { id = 28836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sins of the Sea Witch", description = "That vile worm has earned a thousand deaths!\n\nIt won't be easy. She and her minions are firmly entrenched in this place, but she's bound to be exhausted from her fight with Neptulon.\n\nNow is the time to strike! We won't have another opportunity like this.\n\nRun her through, {name}!", sourceObjective = "Slay Lady Naz'jar in the Throne of Tides.", completion = "Well done, {name}!\n\nKnow that without your aid, things would be far different here.\n\nNot only would I be long dead, but the naga and their allies would have free reign over the sea.\n\nThe king himself shall hear of your heroism in this realm.", sourceObjectiveStatus = "unverified-source-field" }
quests[28837] = { id = 28837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Altered Beasts", description = "We, the blue dragons, have been forced out of our home, Mazthoril. An impostor by the name of Umbranse has taken advantage of us in our weakest hour, and now occupies the cave.\n\nMazthoril is a place of extremely potent magic, and he does not know how to wield it. Even the wildlife suffers.\n\nThe beasts nearby have been altered. Please, {race}, I must ask you a favor. Gather their brains, so I can see if I can undo this Umbranse's wild magic.", sourceObjective = "Obtain 5 Mana-Addled Brains from Altered Beasts.", progress = "Mazthoril belongs to the blue dragonflight. This is not right.", completion = "Let's see what I can do with these...", sourceObjectiveStatus = "unverified-source-field" }
quests[28838] = { id = 28838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Owlbeasts' Defense", description = "What a shame. Whatever Umbranse has done, he has prevented me from undoing his magic.\n\nHe is wiser than I had anticipated.\n\nI do have a backup plan, however. I have seen owlbeasts enter and leave Mazthoril, even after Umbranse took control. Their ancient druidic magic must be capable of disabling Umbranse's. Luckily, I happen to be somewhat of an expert in their methods.\n\nTravel south, to Dun Mandarr. You will find a chest with a dreamcatcher in it.\n\nThat will be your first step.", sourceObjective = "Obtain an Owlbeast Dreamcatcher from Dun Mandarr.", progress = "The owlbeasts' magic will be the key to our retaking of Mazthoril.", completion = "Good. It is just as Jaron described it.", sourceObjectiveStatus = "unverified-source-field" }
quests[28839] = { id = 28839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magic Prehistoric", description = "The owlbeasts' sacred caves are located to the east. Within several of these caves, you should find totems. I want you to approach these totems and gather whatever essence you can from them. The dreamcatcher should absorb this essence for use within Mazthoril.", sourceObjective = "Obtain the Essence of the Claw-Totem, the Essence of the Life-Totem, and the Essence of the Moon-Totem.", progress = "What are you doing, {name}? We need that essence.", completion = "The dreamcatcher is charged.  We are nearly ready to retake Mazthoril.", sourceObjectiveStatus = "unverified-source-field" }
quests[28840] = { id = 28840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterwater", description = "I don't want our gambit to fail, {name}. Such a failure would only draw attention to our efforts, giving Umbranse an opportunity to hone his defenses. No, we have to do this right the first time.\n\nThe Frostwhisper Gorge, to the south, provides us access to powerful ice elementals. The water within these elementals' hulls should amplify the power of your dreamcatcher, ensuring our efforts.\n\nObtain this water, {name}. Then return to our small camp.", sourceObjective = "Obtain 7 Winterwater from Ice Avatars in Frostwhisper Gorge.", progress = "Welcome back.", completion = "<Haleh applies the water to your dreamcatcher.>\n\nYou've done well, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28841] = { id = 28841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arcane Storm Within", description = "Mazthoril's innate magic can wreak unimaginable havoc if mishandled. Umbranse's wanton casting within the cavern has opened up a number of tesseracts - in other words, portals - connecting to other worlds. If I am to return to Mazthoril, these tesseracts must be closed.\n\nThe dreamcatcher will close the portals, buying you safe entrance into Umbranse's lair. First defeat whatever comes out of the tesseracts, then use the dreamcatcher to quickly close them, before anything else spills into this world.", sourceObjective = "Use the Empowered Dreamcatcher to close 5 Arcane Tesseracts within Mazthoril.", completion = "It will take some time for Mazthoril to recover... but she will.\n\nThe blue dragonflight is far from dead.", sourceObjectiveStatus = "unverified-source-field" }
quests[28842] = { id = 28842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umbranse's Deliverance", description = "Umbranse lurks in the back of Mazthoril. His time has come.\n\nUnfortunately, I am unable to join you on this quest. While I'd love to get my hands on that snake, Mazthoril's magic would rip me apart in its current state. No, I need you to finish this for me.\n\nWhen the deed is done, use this charm. It will return you safely to the egress.", sourceObjective = "Slay Umbranse the Spiritspeaker.", progress = "You must finish this for me, {name}.", completion = "You have our thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28843] = { id = 28843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sins of the Sea Witch", description = "Naz'jar! She's the one responsible for this mess.\n\nShe's in here somewhere, {name}. She must be exhausted after that fight with Neptulon.\n\nNow is the time to strike! We won't have another opportunity like this.\n\nI'll handle anything that tries to aid her from this direction.\n\nFind her, {name}, and run her through!", sourceObjective = "Legionnaire Nazgrim wants you to slay Lady Naz'jar.", completion = "Hellscream shall know of your deeds here, {name}.\n\nWithout you, things here would be far worse.\n\nLok'tar ogar, my friend!", sourceObjectiveStatus = "unverified-source-field" }
quests[28845] = { id = 28845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vortex Pinnacle", description = "One of our civilian leaders was taken prisoner by the air elementals.\n\nThey are probably torturing him for information as we speak.\n\nGo to the Vortex Pinnacle, where these foul creatures came from, and look for Itesh.\n\nYou will find the entrance to the Vortex Pinnacle hovering off of the southeastern coast of Uldum.", sourceObjective = "Find Itesh inside the Vortex Pinnacle.", completion = "You actually came here looking for me?", sourceObjectiveStatus = "unverified-source-field" }
quests[28847] = { id = 28847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pursuit of Umbranse", description = "We have isolated Umbranse's position here in Winterspring. It is as I suspected.\n\nUmbranse is at Mazthoril, the cavern that once belonged to the blue dragonflight, in the southwest. My mother, Haleh, will greet you there. She is stationed outside of the cave in a small camp with a few other survivors.\n\nLook for her campfire.", sourceObjective = "Report to Haleh at Beryl Egress in Winterspring.", completion = "You are {name}, yes?\n\nGood, you will serve well. I require the aid of a {class} such as yourself.", sourceObjectiveStatus = "unverified-source-field" }
quests[28848] = { id = 28848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trailing the Spiritspeaker", description = "I have heard tales of Umbranse, though I have not ever met him in person. Rumor has it that he's been collecting magical artifacts, though for what purpose, I couldn't say.\n\nBest pass this information on to a trusted ally. Nymn, the high elf, can be found within Everlook, the large goblin town to the northeast. Tell him all that we learned today.", sourceObjective = "Report to Nymn at Everlook in Winterspring.", completion = "Umbranse... I see. I will carry this information onto my people.\n\nYou will be contacted if you are needed again.", sourceObjectiveStatus = "unverified-source-field" }
quests[28849] = { id = 28849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Skies", description = "I just got word from Orgrimmar that the Warchief wants us to move out. We wouldn't have been ready if it wasn't for your help!\n\nThe plan is for the air fleet to take off immediately, and for the navy to follow close behind. Hellscream will be accompanying the air fleet and specifically requested that you come along with us.\n\nNo time to delay! Go to the Southern Rocketway Terminus here in Azshara, and check in with Friz Groundspin. I'll bring the zeppelin around to pick you up.", sourceObjective = "Check in with Friz Groundspin at the Southern Rocketway Terminus in Azshara.", completion = "Another {class} for the Highlands? Here, sign this indemnification waiver...", sourceObjectiveStatus = "unverified-source-field" }
quests[28850] = { id = 28850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prison Rooftop", description = "I don't understand why the king wants to waste time saving his hide, but if you want to risk your life, then be my guest.\n\nCrowley and his men are holed up upstairs, probably plotting against the king as we speak!", sourceObjective = "Speak to Darius Crowley upstairs in the Stoneward Prison in Gilneas City.", completion = "Greymane's right.  These beasts do not give a damn about our politics.\n\nGilneas needs to stand together.", sourceObjectiveStatus = "unverified-source-field" }
quests[28852] = { id = 28852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soften them Up", description = "At last, reinforcements! I'm so glad you're here. We never imagined just how entrenched the Twilight's Hammer forces are. And there are so many!\n\nSeveral of our drakes have been captured just inside the main hall. Please, break their bonds and free them.\n\nOnce free, together we can scourge these halls clean with flame. Just climb aboard a red drake and call out your targets. You will definitely want to cut down the enemy numbers before delving deeper into the ruins.", sourceObjective = "Free a Red Drake within Grim Batol and use it to destroy 30 Troggs and 15 Twilight's Hammer minions.", progress = "Did you find our wounded drakes? Were they able to help?", completion = "This is great news, {name}! I'm glad our drakes were able to assist you. Thank you for rescuing them from the clutches of the Twilight's Hammer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28853] = { id = 28853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill the Courier", description = "Thank you, {class}, for braving the horrors of this dark and terrible place.\n\nThe bowels of Grim Batol are the heart of Cho'gall's war machine. If we are to stop his machinations throughout the Highlands, we must learn all we can from these depths.\n\nSeek out Drahga Shadowburner within. He is Cho'gall's runner, the link between here and the Bastion of Twilight. We must learn the secrets he carries.", sourceObjective = "Kill Drahga Shadowburner and grab his Missive to Cho'gall.", progress = "What have you discovered, {class}?", completion = "<Tooranu looks over the documents you discovered.>\n\nIt's all here, {name}. Details of how the cult is tearing up the Highlands, who they've sent, where they are, and what they plan to do. Invaluable.\n\nI shall distribute this knowledge to the rest of the Earthen Ring at once. Thank you, friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[28854] = { id = 28854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Closing a Dark Chapter", description = "This terrible place was Alexstrasza's nightmare. During what mortals call the second war, she was chained in the depths below, her tormented offspring forced to serve the demon-corrupted Horde.\n\nAlexstrasza may be free, but the beast known as Erudax still corrupts her offspring below.\n\n<Baleflame's body tenses in anger.>\n\nDestroy him, {class}. Crush him that we may end these horrors once and for all!", sourceObjective = "Slay Erudax, the Duke of Below.", progress = "What of Erudax, {class}?", completion = "So it is done.\n\nWould that I could bring this entire mountain down upon itself, I would.", sourceObjectiveStatus = "unverified-source-field" }
quests[28856] = { id = 28856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sands of Silithus", description = "Let's see... oh, here's a good one! Silithus!\n\nSo, apparently the Cenarion Circle needs assistance with an insect infestation of some sort.\n\n<Vizzie shivers.>\n\nUgh! No thanks, not for me. I'm perfectly happy freezing to death here in Everlook if the alternative is bugs.\n\nHmm... it says here that visitors should speak with Windcaller Proudhorn, and the easiest way to get there is via the path up Un'Goro Crater's northwestern cliffs.\n\nYou interested?", sourceObjective = "Report to Windcaller Proudhorn at Cenarion Hold in Silithus.", completion = "Welcome to Cenarion Hold.\n\n<Windcaller Proudhorn brushes some snow off of your shoulder.>\n\nYou've certainly come from far off.", sourceObjectiveStatus = "unverified-source-field" }
quests[28857] = { id = 28857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blasted Lands: The Other Side of the World", description = "Now here's an interesting one. It says to report to Quartermaster Lungertz at Nethergarde Keep, in the Blasted Lands. That's just about as far as you can get from here!\n\nIt says they're having trouble with Horde attacks. Hmph! I didn't know the Horde even had an outpost in the Blasted Lands! They tend to worry more about demons and less about rivalries down there, as I understand it.\n\nYou'll have to cross the Great Sea, then travel south from the Swamp of Sorrows.\n\nYou interested?", sourceObjective = "Report to Quartermaster Lungertz at Nethergarde Keep.", completion = "For decades has the garrison at Nethergarde held firm against the threat of the Horde and we do not intend to surrender now.", sourceObjectiveStatus = "unverified-source-field" }
quests[28858] = { id = 28858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blasted Lands: The Other Side of the World", description = "Now here's an interesting one.  It says that members of the Horde should talk to Okrilla at Dreadmaul Hold.\n\nHmph! I didn't even know that the Horde held Dreadmaul Hold!\n\nI guess this Okrilla requires help fighting some ogres and the Alliance. You'd think she'd already have her hands full with all the demons down there!\n\nThe best way to Dreadmaul Hold is to cross the Great Sea, then to take the road south from the Swamp of Sorrows.\n\nYou interested?", sourceObjective = "Report to Okrilla at Dreadmaul Hold in the Blasted Lands.", completion = "Our enemies are numerous, {class}. It will take skill and bravery to overcome them all.", sourceObjectiveStatus = "unverified-source-field" }
quests[28859] = { id = 28859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dunes of Silithus", description = "Cenarion Hold, in Silithus, is one of the biggest druid settlements in Kalimdor. Almost as big as Moonglade, mon.\n\nSomeday, maybe Zen'Aliri be headin' on over to Cenarion Hold... fightin' some Twilight's Hammer, healin' the land where the silithid tear it... but Zen'Aliri's master tells him to wait.\n\nSo Zen'Aliri waits.\n\nThe easiest way to get there is that path up Un'Goro Crater's northwestern cliffs.\n\nIf you got no master... there's nothing keepin' you from movin' on.", sourceObjective = "Report to Windcaller Proudhorn at Cenarion Hold in Silithus.", completion = "Welcome to Cenarion Hold, traveler.", sourceObjectiveStatus = "unverified-source-field" }
quests[28860] = { id = 28860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeping the Dragonmaw at Bay", description = "With your help we've thumped the Dragonmaw pretty hard, but still their daily attacks in the Thundermar outskirts persist. We need to keep up the pressure!\n\nWade back into the battle that's raging in the Thundermar ruins to the south and southwest. Kill Dragonmaw marauders and collect the insignias that their greatest warriors wear.", sourceObjective = "Kill Dragonmaw Marauders and collect 8 Dragonmaw Insignias. Named characters within the Thundermar Ruins will also carry insignias.", progress = "How goes the fight, {class}?", completion = "Aye, that's how it's done! With heroes like you taking care of business, I'm proud to be a part of the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[28861] = { id = 28861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight Like a Wildhammer", description = "<Blundy upends his cup.>\n\nI'm all outta ale, {name}!\n\nHead out into the Thundermar Ruins and see if there's any left, before those grungy Dragonmaw get their mouths on it.\n\nFeel free to have a few sips, yerself. A mug of ol' Thundermar's finest will fortify yer fightin' skills.", sourceObjective = "Collect 10 Kegs of Thundermar Ale from the Thundermar Ruins. Carfeul - it's got some kick!", progress = "Got sumthun'?", completion = "Oh aye, quite a haul!\n\nThis'll last me until... oh say probably tomorrow.", sourceObjectiveStatus = "unverified-source-field" }
quests[28862] = { id = 28862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Leave a Dinner Behind", description = "Refugees are still pouring into Thundermar from the fighting, and I'm hungry! I mean them. The refugees, they're hungry.\n\nGet me some food from the Thundermar Ruins! Scour the ruins to the south, east, and southwest for any stores that still remain. Especially them big hocks of ham. I love those! Er, the refugees do.\n\nAnd see if you can find some of them little cocktail weenies.", sourceObjective = "Gather 10 Wildhammer Food Stores from the Thundermar Ruins.", progress = "Got some eats?", completion = "Oh hey, yer just in time! I was working up a huge appetite, workin' so hard to feed these hungry refugees. Yessir.", sourceObjectiveStatus = "unverified-source-field" }
quests[28863] = { id = 28863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warlord Halthar is Back", description = "He's at it again, {name}. Warlord Halthar... terror of the shire. He and his drake were spotted causing trouble to the south, among the Thundermar Ruins.\n\nKill Halthar, {name}! We'll send in some warbrands to help out once you engage.", sourceObjective = "Slay Warlord Halthar.", completion = "Grim business, but well done all the same. Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28864] = { id = 28864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beer Run", description = "After my sister's wedding, I developed a taste for that Thunderbrew Lager that Kurdran had imported from Dun Morogh. More is on the way, but our caravan keeps getting jumped by the Dragonmaw!\n\nHead on up to the southeast side of Thunderstrike Mountain and catch up with the caravan. Look for a fellow named Hammelhand at the side of the road, and help him get the booze through the pass.\n\nJust get it as far as Kirthaven, and we'll take it from there.", sourceObjective = "Speak with Hammelhand on the road southeast of Thunderstrike Mountain and escort a supply caravan to Kirthaven.", completion = "Go figure. Never thought I'd develop a taste for imported draft. Thanks, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[28865] = { id = 28865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of the Warmatron", description = "Our venerable warmatron, Okrilla, has sent me to the far reaches of the world in search of suitable heroes that would join our cause. Are you interested in strengthening the Horde's grasp over the Eastern Kingdoms? Then take this portal to the Blasted Lands and report to Okrilla at Dreadmaul Hold!", sourceObjective = "Report to Okrilla at Dreadmaul Hold in Blasted Lands.", completion = "Silithus, such a worthless piece of land. It is a wonder that the great cataclysm did not sunder it fully!", sourceObjectiveStatus = "unverified-source-field" }
quests[28866] = { id = 28866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Stonecore", description = "You say that this Millhouse Manastorm and High Priestess Azil were to meet inside the Stonecore?\n\nSounds big.  We'd best get on their trail.  We don't want the Twilight's Hammer pulling off something big right under our noses.\n\nSpeak to Earthwarden Yrsa inside the Stonecore.  She's been stationed there to make sure the Twilight's Hammer doesn't try to retake the Temple of Earth.", sourceObjective = "Speak to Earthwarden Yrsa inside the Stonecore.", completion = "It's about time they sent someone to help.\n\nMillhouse Manastorm?  It sounds like we're both after the same person.", sourceObjectiveStatus = "unverified-source-field" }
quests[28867] = { id = 28867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nethergarde Needs You!", description = "Nethergarde needs you, {class}! I have been sent here by Quartermaster Lungertz to head off Okrilla's nefarious lackeys and to recruit able-bodied heroes of the Alliance! Help us fight off the Horde!\n\nIf you are willing, take this portal in front of me to the Blasted Lands and speak with the quartermaster.", sourceObjective = "Speak to Quartermaster Lungertz at Nethergarde Keep in Blasted Lands.", completion = "Silithus, not such a great place, eh? We get a lot of you from there...", sourceObjectiveStatus = "unverified-source-field" }
quests[28868] = { id = 28868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The View from Down Here", description = "We need to halt the construction on this Frostmane village. If we let them get too entrenched, it will be more difficult to keep them from settling here permanently.\n\nIt's time to give those brutes a gnome's-eye view of the world! Take this gnomish viewpoint equalizer and use it on the Frostmane builders to bring them down to our level. They won't be able to lift their tools and construction will come to a standstill.", sourceObjective = "Use the Viewpoint Equalizer on 5 Frostmane Builders in Frostmane Retreat.", progress = "Did you show them what it's like to be a gnome?", completion = "Well done, {name}. That'll teach them not to mess with us in our home!", sourceObjectiveStatus = "unverified-source-field" }
quests[28869] = { id = 28869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pebble", description = "If you hadn't noticed, there's a very small elemental that has taken a liking to you. If you stay on the ground for even a few moments, I'm sure you'll spot him.\n\nYou seem to be quite adept at making friends down here. A good talent to have.", sourceObjective = "Speak to Pebble in the Shuddering Spires. If you stay on the ground long enough, he should come out of hiding to find you.", completion = "<Pebble seems quite happy to meet you.>", sourceObjectiveStatus = "unverified-source-field" }
quests[28870] = { id = 28870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Lost City", description = "We might've taken Neferset City, but the Neferset have a new seat of power.\n\nThanks to Siamat, the powerful djinn of the south wind, the Neferset have become considerably more dangerous.\n\nWe just learned that some of Nadun's ambushed reconnaissance party managed to secure the entrance to the Lost City.\n\nGo find Captain Hadan and get whatever information you need to bring down Siamat and the Neferset scum.", sourceObjective = "Speak to Captain Hadan inside the Lost City of the Tol'vir.", completion = "Hail, {name}.  Nadun spoke highly of you.\n\nAre you here to aid us?", sourceObjectiveStatus = "unverified-source-field" }
quests[28871] = { id = 28871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Wildhammer", description = "The Wildhammer grow bold with their new Alliance allies. They dare press across the river. Drive them back!\n\nSeek out and crush the Wildhammer warbrands who fight in the riverbed and within the Thundermar Ruins along the north bank. The best among them carry insignias - gather them for me to prove your allegiance to the Dragonmaw cause.", sourceObjective = "Kill Wildhammer Warbrands to collect 8 Wildhammer Insignias. Named characters within the Thundermar Ruins will also carry insignias.", progress = "Show me the insignias you've collected, {class}.", completion = "Look what we have here! A single Horde {class} can demolish the Wildhammer by the dozen. What hope do they have now?", sourceObjectiveStatus = "unverified-source-field" }
quests[28872] = { id = 28872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Total War", description = "Some of the Wildhammer still cling to the hope of reclaiming the Thundermar Ruins to the north, across the river. Burn them out! Smash open kegs of Thundermar ale. That wicked brew is potent enough to explode when set aflame.\n\nDon't ask me why.\n\nAnd don't ask me how they drink the stuff.", sourceObjective = "Smash 10 Thundermar Ale Kegs within the Thundermar Ruins.", completion = "Yes, yes. Burn them out, as you would flush groundhogs from their holes...\n\nWell done, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28873] = { id = 28873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Another Maw to Feed", description = "<Griff's stomach growls.>\n\nStill hungry. It's like ... every day, I'm hungry.\n\nI hear there's more food stashed up in the Thundermar Ruins across the river to the north, where all the fighting is. Bring some to my mouth.", sourceObjective = "Gather 10 Wildhammer Food Stores from the Thundermar Ruins.", progress = "<Griff licks his lips.>", completion = "<Griff greedily snatches the heap of food, enough to feed dozens of men.>\n\nGreat! This'll tide me over for ... hours!", sourceObjectiveStatus = "unverified-source-field" }
quests[28874] = { id = 28874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hook 'em High", description = "The Wildhammer can train war gryphons faster than we can subvert and control drakes. We can't let them continue to outnumber us!\n\nHunt gryphon riders flying over the river north of Bloodgulch. Take this hook and fling it at them as they fly by. Their momentum will hurl them from their mount, right to your feet. Kill the dismounted gryphon riders!", sourceObjective = "Use the Barbed Fleshhook to dismount and kill 4 Thundermar Gryphon Riders.", completion = "You made that look easy, {name}.\n\nGet the Wildhammer off of their mounts and they're nothing!", sourceObjectiveStatus = "unverified-source-field" }
quests[28875] = { id = 28875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Down the High Shaman", description = "Our scouts in the field report that High Shaman MacKilligan has moved out of Thundermar and is fighting amidst the Thundermar Ruins northwest of here, across the river.\n\nHe's a dangerous one, {name}, responsible for the deaths of many a Dragonmaw. He WILL be destroyed, that is not the question.\n\nThe question is: will you be the one to earn the glory of the kill?", sourceObjective = "Slay High Shaman MacKilligan.", completion = "The High Shaman has been brought down! Thundermar will no doubt try to send others, but on this day, the Dragonmaw are triumphant.", sourceObjectiveStatus = "unverified-source-field" }
quests[28876] = { id = 28876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Mor'shan Rampart", description = "Kadrak at the Mor'shan Rampart to the north is calling for aid.\n\nThe rampart rests on the border between the Northern Barrens and Ashenvale. It is the front line in the fight against the Alliance.\n\nWe're driving the night elves out of the forest. We'll claim its resources for the Horde!\n\nTo get there, take the Gold Road north out of the Crossroads.\n\nDestiny calls!", sourceObjective = "Report to Kadrak at the Mor'shan Rampart on the border between the Northern Barrens and Ashenvale.", sourceObjectiveStatus = "unverified-source-field" }
quests[28877] = { id = 28877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Call Him Swiftdagger. He Kills Harpies.", description = "There's an orc who lives in the west. At the frayed edge of the cataclysm's swath of destruction.\n\nThey call him Swiftdagger, {name}. They call him that because ... his ... actually I think that's just his name.\n\n<Nozzlepot shrugs.>\n\nAnyway, he's a harpy-killing machine. He kills harpies. Loves it. It's a living. Go and see him! See how it's done. Live the dream. You might make a career out of it.", sourceObjective = "Locate Darsok Swiftdagger in Northern Barrens.There's an orc who lives in the west. At the frayed edge of the cataclysm's swath of destruction.\n\nThey call him Swiftdagger, {name}. They call him that because... his... actually I think that's just his name.\n\n<Nozzlepot shrugs.>\n\nAnyway, he's a harpy-killing machine. He kills harpies. Loves it. It's a living. Go and see him! See how it's done. Live the dream. You might make a career out of it.", sourceObjectiveStatus = "unverified-source-field" }
quests[28878] = { id = 28878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Winter Veil Gift" }
quests[28879] = { id = 28879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back To The Orphanage", description = "We had the best time with you, {name}. We wish you could be our <daddy/mama> now, but you have to take us back to Orphan Matron Aria in Dalaran.\n\nMaybe you could come visit us again sometime? We loved meeting Winterfin hatchlings and getting to see the dragon queen. No one will believe us when we say we met a Great One!\n\nWe going to miss you, {name}. We promise to write letter sometime, oki?You will be able to choose one of these rewards:", sourceObjective = "Return your ward to the Dalaran orphanage by handing in the Oracle Orphan Whistle to Orphan Matron Aria in Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[28880] = { id = 28880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back To The Orphanage", description = "Know what? You not so bad after all, {name}. You take Kekek a lot of fun places. Kekek meet a lot of new friends and do things no other pup get to do.\n\nYou, and Hemet Nesingwary, and Snowfall Glade pups all new best friends. Maybe sometime you bring Kekek that green hills book? Kekek promise to write sometimes, too, tell you how things go. Maybe even be nice to big-tongue kids sometimes.\n\nKekek gotta go back to orphan-lady Aria now, back in purple human city.You will be able to choose one of these rewards:", sourceObjective = "Return your ward to the Dalaran orphanage by handing in the Wolvar Orphan Whistle to Orphan Matron Aria in Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[28881] = { id = 28881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prospector Gunstan", description = "Say... you haven't been to Southmoon Ruins yet, have you?  Oh you simply MUST.  They have all sorts of fascinating titan artifacts.  Head west, and look for the Explorers' League tents.", sourceObjective = "Report to Prospector Gunstan at Southmoon Ruins in Tanaris.", completion = "What, you here to help?", sourceObjectiveStatus = "unverified-source-field" }
quests[28882] = { id = 28882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory in Tol Barad", description = "We fought hard to get a foothold on this ugly rock and there is no way we are going to let the Horde get in the way of our plans.  Keeping control of Tol Barad is our first priority and we need your help, {name}.  Fight your way to victory in Tol Barad and return to me word of your triumph.", sourceObjective = "Win a Tol Barad battle and return to Major Marsden at Baradin Base Camp in Tol Barad Peninsula.", progress = "Were you victorious against the Horde?", completion = "What's that smell?  Ah.....Smells like victory.  Your efforts in Tol Barad are a great triumph for the entire Alliance, your contributions will not be forgotten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28884] = { id = 28884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory in Tol Barad", description = "Maintaining control of Tol Barad is the key to our strategic plans here in the Eastern Kingdoms, {race}.  We must do whatever it takes to keep the Alliance off this island and that means we need your help.  Fight with everything you have to win control of Tol Barad and bring me word of victory.", sourceObjective = "Win a Tol Barad battle and return to Colonel Karzag at Hellscream's Grasp in Tol Barad Peninsula.", progress = "Were you victorious against the Alliance?", completion = "You bring word of victory, just as I expected!  Any triumph in Tol Barad is in turn a triumph for the Horde.  Have no doubt, your efforts here will be rewarded.", sourceObjectiveStatus = "unverified-source-field" }
quests[28885] = { id = 28885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mr. Goldmine's Wild Ride", description = "Okay, {name}, we need to get to the earth portal at the back of the cave.\n\nI've \"procured\" a ride for us. Why walk when we can ride in style? I hope you don't mind mine carts.\n\nLet me know when you're ready.", sourceObjective = "Ride the mine cart with Initiate Goldmine to the end of the line.", completion = "Oh no! My weapons and totems!\n\nThey're destroyed!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[28905] = { id = 28905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daily Heroic Random (1st) (Cataclysm)" }
quests[28906] = { id = 28906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daily Heroic Random (Nth)" }
quests[28907] = { id = 28907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daily Normal Random (1st)" }
