quests[28909] = { id = 28909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sauranok Will Point the Way", description = "I see you haven't yet spoken to my advisor, Sauranok the Mystic. He has been at my side since our campaign together in Northrend.\n\nTo assault the Twilight Highlands, we're going to need a map of the shoreline. I have tasked Sauranok with digging up this information. See if he can use your assistance! He is standing right next to me.", sourceObjective = "Speak with Sauranok the Mystic at Grommash Hold in Orgrimmar.", completion = "<Sauranok nods toward you.>\n\n{class}.", sourceObjectiveStatus = "unverified-source-field" }
